<?php use App\Support\Ui; ?>
<div class="page-heading"><div><span class="eyebrow">YOUR SCHEDULE</span><h1>My interviews</h1><p>Upcoming, completed, and cancelled interviews in one place.</p></div><a class="button primary" href="<?= $e($url('candidate/book')) ?>"><?= Ui::icon('plus') ?>Book interview</a></div>
<div class="interview-tabs" role="tablist" aria-label="Interview status"><button class="active" type="button" role="tab" data-tab="upcoming" aria-selected="true">Upcoming <span><?= count($upcoming) ?></span></button><button type="button" role="tab" data-tab="past" aria-selected="false">Past <span><?= count($past) ?></span></button><button type="button" role="tab" data-tab="cancelled" aria-selected="false">Cancelled <span><?= count($cancelled) ?></span></button></div>
<?php foreach(['upcoming'=>$upcoming,'past'=>$past,'cancelled'=>$cancelled] as $section=>$items): ?><section class="interview-tab-panel <?= $section === 'upcoming' ? 'active' : '' ?>" data-panel="<?= $e($section) ?>" <?= $section === 'upcoming' ? '' : 'hidden' ?>>
<?php if (!$items): ?><div class="empty-state card"><div class="empty-icon"><?= Ui::icon($section === 'cancelled' ? 'trash' : 'calendar') ?></div><h3>No <?= $e($section) ?> interviews</h3><p><?= $section === 'upcoming' ? 'When you confirm an interview, it will appear here.' : 'There are no interview records in this section.' ?></p><?php if($section === 'upcoming'): ?><a class="button primary" href="<?= $e($url('candidate/book')) ?>">Book interview</a><?php endif; ?></div>
<?php else: ?><div class="interview-list"><?php foreach($items as $item): ?><article class="interview-list-card <?= $item['status'] === 'CANCELLED' ? 'cancelled' : '' ?>"><div class="date-tile"><strong><?= $e($item['start_local']->format('d')) ?></strong><?= $e(strtoupper($item['start_local']->format('M'))) ?></div><div class="interview-list-copy"><div><h2><?= $e($item['company_name']) ?></h2><span class="badge <?= $item['interview_type'] === 'TOOL' ? 'purple' : 'neutral' ?>"><?= $e(ucfirst(strtolower($item['interview_type']))) ?></span><?php if($item['status'] === 'CANCELLED'): ?><span class="badge danger-badge">Cancelled</span><?php endif; ?></div><p><?= $e($item['job_role']) ?> · <?= $e($item['technology_name']) ?></p><small><?= Ui::icon('clock') ?><?= $e($item['display_time']) ?> · <?= $e($item['duration_minutes']) ?> min<?php if($item['support_person_name']): ?> · Support: <?= $e($item['support_person_name']) ?><?php endif; ?></small></div><div class="interview-list-actions"><a class="button secondary" href="<?= $e($url('candidate/interview?id=' . $item['id'])) ?>">Details</a><?php if($section === 'upcoming' && $item['can_change']): ?><a class="text-link" href="<?= $e($url('candidate/interview/reschedule?id=' . $item['id'])) ?>">Reschedule</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section><?php endforeach; ?>
